contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(
        address maker,
        bool isCall,
        bool isLong,
        address baseAsset,
        uint256 strike,
        uint256 premium,
        uint256 duration,
        uint256 expiration,
        uint256 nonce,
        address[] memory whitelist,
        address[] memory floorTokens,
        C.ERC20Asset[] memory erc20Assets,
        C.ERC721Asset[] memory erc721Assets
    ) public {
        require(baseAsset != address(0), "baseAsset zero");

        C.Order memory order = C.Order({
            maker: maker,
            isCall: isCall,
            isLong: isLong,
            baseAsset: baseAsset,
            strike: strike,
            premium: premium,
            duration: duration,
            expiration: expiration,
            nonce: nonce,
            whitelist: whitelist,
            floorTokens: floorTokens,
            erc20Assets: erc20Assets,
            erc721Assets: erc721Assets
        });

        bytes32 h = c.hashOrder(order);
        bytes32 ho = c.hashOppositeOrder(order);

        C.Order memory opposite = C.Order({
            maker: maker,
            isCall: isCall,
            isLong: !isLong,
            baseAsset: baseAsset,
            strike: strike,
            premium: premium,
            duration: duration,
            expiration: expiration,
            nonce: nonce,
            whitelist: whitelist,
            floorTokens: floorTokens,
            erc20Assets: erc20Assets,
            erc721Assets: erc721Assets
        });

        bytes32 directOppositeHash = c.hashOrder(opposite);

        assert(ho == directOppositeHash);
    }
}

