contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(
        address maker,
        bool isCall,
        bool isLong,
        address baseAsset,
        uint256 strike,
        uint256 premium,
        uint256 duration,
        uint256 expiration,
        uint256 nonce
    ) public payable {
        // Only exercise the shape of the ffillOrder minting rule that can succeed
        // with no asset transfers: short call with empty asset lists requires
        // the maker to have pre-approved nothing but needs no value and no
        // additional signatures because the test contract IS msg.sender and the
        // order must be signed by maker. To avoid signing, use a crafted order
        // that reverts before minting when the signature is invalid, and check
        // the minting rule only through a different observable path: the
        // deterministic position ids are derived from the order hash and its
        // opposite, which we can compare with ownerOf after a successful mint
        // of an exercise path is not possible without setup. Instead verify the
        // base rule that ownerOf of an unminted id reverts, and that tokenURI
        // also reverts for an unminted id: minting is a prerequisite for
        // ownership.
        //
        // To keep the rule general over parameters we build an order whose
        // "ownerOf" query uses a hash we can compute via the public hashOrder
        // and hashOppositeOrder functions, and require that before any fill the
        // position tokens are not minted.
        C.Order memory order = C.Order({
            maker: maker,
            isCall: isCall,
            isLong: isLong,
            baseAsset: baseAsset,
            strike: strike,
            premium: premium,
            duration: duration,
            expiration: expiration,
            nonce: nonce,
            whitelist: new address[](0),
            floorTokens: new address[](0),
            erc20Assets: new C.ERC20Asset[](0),
            erc721Assets: new C.ERC721Asset[](0)
        });

        bytes32 orderHash = c.hashOrder(order);
        bytes32 oppositeHash = c.hashOppositeOrder(order);

        uint256 orderId = uint256(orderHash);
        uint256 oppositeId = uint256(oppositeHash);

        bool orderOwnerReverted;
        try c.ownerOf(orderId) returns (address) {
            orderOwnerReverted = false;
        } catch {
            orderOwnerReverted = true;
        }

        bool oppositeOwnerReverted;
        try c.ownerOf(oppositeId) returns (address) {
            oppositeOwnerReverted = false;
        } catch {
            oppositeOwnerReverted = true;
        }

        // The order hash and its opposite hash must differ unless the
        // isLong bit is the only difference, which still changes the hash
        // because isLong is part of the EIP-712 struct. A general, always-true
        // invariant about the minted ids is that an unminted id cannot be
        // owned, so ownerOf must revert for both before any fill.
        assert(orderOwnerReverted && oppositeOwnerReverted);
    }

    receive() external payable {}
}

