contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(
        uint256 nonce,
        uint256 duration,
        uint256 strike,
        uint256 premium,
        bool isCall,
        bool isLong
    ) public payable {
        duration = duration % 1000;
        strike = strike % 1000;
        premium = premium % 1000000;

        C.Order memory order = C.Order({
            maker: address(this),
            isCall: isCall,
            isLong: isLong,
            baseAsset: c.weth(),
            strike: strike,
            premium: premium,
            duration: duration,
            expiration: block.timestamp + 1,
            nonce: nonce,
            whitelist: new address[](0),
            floorTokens: new address[](0),
            erc20Assets: new C.ERC20Asset[](0),
            erc721Assets: new C.ERC721Asset[](0)
        });

        uint256 expectedPositionId = uint256(c.hashOppositeOrder(order));
        uint256 valueSent = 0;
        if (!isLong && (!isCall || premium > 0)) {
            valueSent = c.weth() == address(0) ? 0 : (isCall ? premium : strike + premium);
        }
        require(address(this).balance >= valueSent, "insufficient balance");

        bool filled;
        try c.fillOrder{value: valueSent}(order, "", new uint256[](0)) returns (uint256 positionId) {
            filled = true;
            assert(positionId == expectedPositionId);
        } catch {
            filled = false;
        }

        if (filled) {
            assert(c.ownerOf(expectedPositionId) == address(this));
            assert(c.ownerOf(uint256(c.hashOrder(order))) == address(this));
            assert(c.positionExpirations(expectedPositionId) == block.timestamp + duration);
        }
    }

    receive() external payable {}
}

