contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    receive() external payable {}

    function run(
        address maker,
        uint256 nonce,
        uint256 premium
    ) public payable {
        require(maker != address(0), "bad maker");
        require(maker != address(this), "maker must not be test");
        require(premium > 0, "bad premium");

        address base = address(0xdeadbeef);

        C.Order memory order = C.Order({
            maker: maker,
            isCall: false,
            isLong: true,
            baseAsset: base,
            strike: 0,
            premium: premium,
            duration: 1,
            expiration: block.timestamp + 1000,
            nonce: nonce,
            whitelist: new address[](0),
            floorTokens: new address[](0),
            erc20Assets: new C.ERC20Asset[](0),
            erc721Assets: new C.ERC721Asset[](0)
        });

        C.Order memory opposite = order;
        opposite.isLong = false;
        bytes32 oppositeHash = c.hashOrder(opposite);
        uint256 expectedShortId = uint256(oppositeHash);

