contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(
        uint256 strike,
        uint256 duration,
        uint256 expiration,
        uint256 nonce,
        address erc20Token,
        uint256 erc20Amount,
        address erc721Token,
        uint256 erc721Id,
        address floorToken,
        uint256 floorId
    ) public payable {
        require(strike > 0, "strike must be positive");
        require(duration > 0, "duration must be positive");
        require(block.timestamp < expiration, "expiration must be in the future");
        require(erc20Token != address(0), "erc20 token must be non-zero");
        require(erc721Token != address(0), "erc721 token must be non-zero");
        require(floorToken != address(0), "floor token must be non-zero");

        C.ERC20Asset[] memory erc20Assets = new C.ERC20Asset[](1);
        erc20Assets[0] = C.ERC20Asset(erc20Token, erc20Amount);

        C.ERC721Asset[] memory erc721Assets = new C.ERC721Asset[](1);
        erc721Assets[0] = C.ERC721Asset(erc721Token, erc721Id);

        address[] memory whitelist = new address[](0);

        address[] memory floorTokens = new address[](1);
        floorTokens[0] = floorToken;

        C.Order memory order = C.Order({
            maker: address(this),
            isCall: true,
            isLong: true,
            baseAsset: erc20Token,
            strike: strike,
            premium: 0,
            duration: duration,
            expiration: expiration,
            nonce: nonce,
            whitelist: whitelist,
            floorTokens: floorTokens,
            erc20Assets: erc20Assets,
            erc721Assets: erc721Assets
        });

        uint256[] memory inputFloors = new uint256[](1);
        inputFloors[0] = floorId;

        bytes memory sig = new bytes(0);

        // Setup: mint the required assets into this test contract, which acts as msg.sender for c calls.
        // These external setup calls are not calls on c and therefore need no special treatment.
        (bool mintedErc20, ) = erc20Token.call(
            abi.encodeWithSignature("mint(address,uint256)", address(this), erc20Amount)
        );
        require(mintedErc20, "erc20 mint failed");

        (bool mintedErc721, ) = erc721Token.call(
            abi.encodeWithSignature("mint(address,uint256)", address(this), erc721Id)
        );
        require(mintedErc721, "erc721 mint failed");

        (bool mintedFloor, ) = floorToken.call(
            abi.encodeWithSignature("mint(address,uint256)", address(this), floorId)
        );
        require(mintedFloor, "floor mint failed");

        // Approve c to pull the assets.
        (bool okApproveERC20, ) = erc20Token.call(
            abi.encodeWithSignature("approve(address,uint256)", address(c), erc20Amount)
        );
        require(okApproveERC20, "erc20 approve failed");

        (bool okApproveERC721, ) = erc721Token.call(
            abi.encodeWithSignature("approve(address,uint256)", address(c), erc721Id)
        );
        require(okApproveERC721, "erc721 approve failed");

        (bool okApproveFloor, ) = floorToken.call(
            abi.encodeWithSignature("approve(address,uint256)", address(c), floorId)
        );
        require(okApproveFloor, "floor approve failed");

        // The contract's safeTransferFrom sometimes calls onERC721Received, which must not revert.

        uint256 posId = c.fillOrder(order, sig, inputFloors);

        uint256 strikeBefore = strike;

        c.exercise(order, inputFloors);

        bool exercised = c.exercisedPositions(uint256(c.hashOrder(order)));

        uint256 erc20Received = 0;
        (bool balOk, bytes memory balData) = erc20Token.staticcall(
            abi.encodeWithSignature("balanceOf(address)", address(this))
        );
        if (balOk && balData.length >= 32) {
            erc20Received = abi.decode(balData, (uint256));
        }

        uint256 nftOwnerId = 0;
        (bool ownerOk, bytes memory ownerData) = erc721Token.staticcall(
            abi.encodeWithSignature("ownerOf(uint256)", erc721Id)
        );
        if (ownerOk && ownerData.length >= 32) {
            nftOwnerId = uint256(uint160(abi.decode(ownerData, (address))));
        }

        assert(exercised && erc20Received >= strikeBefore && nftOwnerId == uint256(uint160(address(this))));
    }

    receive() external payable {}
}

