contract InvMutTest {
    C c;
    bool private _entered;
    constructor(C _c) { c = _c; }

    function run(
        address maker,
        bool isCall,
        bool isLong,
        address baseAsset,
        uint256 strike,
        uint256 premium,
        uint256 duration,
        uint256 expiration,
        uint256 nonce,
        address[] memory whitelist,
        address[] memory floorTokens,
        C.ERC20Asset[] memory erc20Assets,
        C.ERC721Asset[] memory erc721Assets
    ) public payable {
        require(!_entered, "reentrant");
        _entered = true;
        C.Order memory order = C.Order({
            maker: maker,
            isCall: isCall,
            isLong: isLong,
            baseAsset: baseAsset,
            strike: strike,
            premium: premium,
            duration: duration,
            expiration: expiration,
            nonce: nonce,
            whitelist: whitelist,
            floorTokens: floorTokens,
            erc20Assets: erc20Assets,
            erc721Assets: erc721Assets
        });

        bytes32 orderHash = c.hashOrder(order);
        bool cancelledBefore = c.cancelledOrders(orderHash);

        bool revertFlag = false;
        try c.cancel(order) {
            revertFlag = false;
        } catch {
            revertFlag = true;
        }

        bool cancelledAfter = c.cancelledOrders(orderHash);

        assert(!revertFlag && !cancelledBefore && cancelledAfter);
    }

    receive() external payable {}
}

